import{_ as a,o as r,c as t,a2 as i}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"MusicHud-TuneWeave","description":"","frontmatter":{},"headers":[],"relativePath":"projects/music-hud-paper/README.md","filePath":"projects/music-hud-paper/README.md"}'),s={name:"projects/music-hud-paper/README.md"};function n(o,e,l,u,d,c){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="musichud-tuneweave" tabindex="-1">MusicHud-TuneWeave <a class="header-anchor" href="#musichud-tuneweave" aria-label="Permalink to &quot;MusicHud-TuneWeave&quot;">​</a></h1><p>MusicHud TuneWeave 是由 <a href="https://github.com/MOPELotus/TuneWeave" target="_blank" rel="noreferrer">TuneWeave</a> 驱动的 Minecraft 音乐播放与同步项目，支持点歌、队列、歌词、HUD 和多人同步。</p><p>MusicHud TuneWeave is an independent LGPL fork of <a href="https://github.com/Etern-34520/MusicHud" target="_blank" rel="noreferrer">MusicHud</a>, also derived from the former MusicHud-Paper implementation. It is not an official MusicHud release and does not guarantee API or protocol compatibility with upstream MusicHud.</p><h2 id="支持范围" tabindex="-1">支持范围 <a class="header-anchor" href="#支持范围" aria-label="Permalink to &quot;支持范围&quot;">​</a></h2><p>本分支提供 Minecraft <strong>1.21.11</strong> 的 Fabric 和 NeoForge 客户端模组，运行需要 Java 21。Paper、Velocity、BungeeCord 插件由 <a href="https://github.com/MOPELotus/MusicHud-TuneWeave/tree/plugin" target="_blank" rel="noreferrer">plugin 分支</a>构建。</p><p>群组服只在代理端安装对应插件，所有后端均不安装；独立 Paper 单服直接安装 Paper 插件。客户端仍需安装模组。详见<a href="./docs/deployment.html">部署说明</a>。</p><h2 id="安装与音乐服务" tabindex="-1">安装与音乐服务 <a class="header-anchor" href="#安装与音乐服务" aria-label="Permalink to &quot;安装与音乐服务&quot;">​</a></h2><ol><li>安装匹配 Minecraft 版本与加载器的 ModernUI；Fabric 还需要 Fabric API。</li><li>将 <code>musichud-tuneweave-fabric-&lt;version&gt;+&lt;mc-version&gt;.jar</code> 或 <code>musichud-tuneweave-neoforge-&lt;version&gt;+&lt;mc-version&gt;.jar</code> 放入 mods 目录。</li><li>在游戏内设置页下载或配置 TuneWeave；独立实例默认地址为 <a href="http://127.0.0.1:7832" target="_blank" rel="noreferrer">http://127.0.0.1:7832</a>。</li></ol><p>依赖版本以本分支 gradle.properties 和模组元数据为准。26.2 使用<a href="https://github.com/MOPELotus/ModernUI-MC/releases" target="_blank" rel="noreferrer">配套 ModernUI 分支</a>。TuneWeave 自动下载会校验 SHA-256，升级仅清理受管理的旧二进制，保留无关用户文件。</p><p>音乐平台凭据由客户端持有，不发送给 Minecraft 服务器。项目命名空间为 musichud_tuneweave，不能与上游 MusicHud 并装；配置和 Uni 数据使用独立目录，不自动迁移旧数据。</p><h2 id="构建与测试" tabindex="-1">构建与测试 <a class="header-anchor" href="#构建与测试" aria-label="Permalink to &quot;构建与测试&quot;">​</a></h2><p>构建使用 JDK 25。</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> common:test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fabric:build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> neoforge:build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rerun-tasks</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Windows 使用 gradlew.bat。网络/下载集成测试默认不运行，可显式执行 common:test -PintegrationTests。产物位于 fabric/build/libs 和 neoforge/build/libs，使用不含 -sources/-dev-shadow 后缀的分发 JAR。</p><h2 id="许可证与致谢" tabindex="-1">许可证与致谢 <a class="header-anchor" href="#许可证与致谢" aria-label="Permalink to &quot;许可证与致谢&quot;">​</a></h2><p>本项目遵循 <a href="./license.html">LGPL-3.0</a>，保留上游作者及贡献者归属。Java 包名为 indi.mopelotus.musichud。</p>',16)])])}const m=a(s,[["render",n]]);export{h as __pageData,m as default};
